219:      */
220:     private String resolveRepositoryClass(
221:             ClassOrInterfaceType type,
222:             CompilationUnit unit,
223:             Map<String, ClassOrInterfaceDeclaration> classes) {
224: 
225:         try {
226:             var resolved = type.resolve();
227: 
228:             if (resolved.isReferenceType()) {
229:                 String qualified = resolved.asReferenceType()
230:                         .getQualifiedName();
231: 
232:                 if (classes.containsKey(qualified)) {
233:                     return qualified;
234:                 }
235:             }
236: 
237:         } catch (RuntimeException exception) {
238:             // Continue with conservative source lookup.
239:         }
240: 
241:         String name = type.getNameWithScope();
242: 
243:         if (name.contains(".")) {
244:             return classes.containsKey(name) ? name : null;
245:         }
246: 
247:         String packageName = unit.getPackageDeclaration()
248:                 .map(declaration ->
249:                         declaration.getNameAsString())
250:                 .orElse("");
251: 
252:         String samePackage = packageName.isEmpty()
253:                 ? name
254:                 : packageName + "." + name;
255: 
256:         if (classes.containsKey(samePackage)) {
257:             return samePackage;
258:         }
259: 
260:         List<String> imports = unit.getImports()
261:                 .stream()
262:                 .filter(declaration ->
263:                         !declaration.isStatic()
264:                                 && !declaration.isAsterisk())
265:                 .map(declaration ->
266:                         declaration.getNameAsString())
267:                 .filter(qualified ->
268:                         qualified.endsWith("." + name)
269:                                 && classes.containsKey(qualified))
270:                 .distinct()
271:                 .toList();
272: 
273:         return imports.size() == 1 ? imports.get(0) : null;
274:     }
275: }

